fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 and that Fibonacci(n) < 2^31, so no overflow will occur.
    assert!(n >= 2, "n must be at least 2");
    let mut ret = Vec::with_capacity(n);
    
    // Base cases
    ret.push(0);
    ret.push(1);
    
    // Build up the rest of the sequence
    for i in 2..n {
        // Safe to unwrap: by assumption, no overflow in i32
        let next = ret[i - 1] + ret[i - 2];
        ret.push(next);
    }
    
    ret
}